func TestMCPConfigNoArgJSONReturnsClientsAndSafety(t *testing.T) {
	t.Setenv("STRADDLE_TOKEN", "fixture-secret-token-never-print")

	stdout, stderr, err := runCLIForDocsTest(t, "mcp", "config", "--json")
	if err != nil {
		t.Fatalf("mcp config --json returned error: %v", err)
	}
	if stderr != "" {
		t.Fatalf("mcp config wrote stderr: %q", stderr)
	}

	var got mcpConfigResponse
	if err := json.Unmarshal([]byte(stdout), &got); err != nil {
		t.Fatalf("mcp config --json emitted invalid JSON: %v\n%s", err, stdout)
	}
	if got.Command != "mcp config" {
		t.Fatalf("command = %q, want mcp config", got.Command)
	}
	wantClients := []string{"claude-desktop", "codex", "cursor", "stdio", "all"}
	if strings.Join(got.AvailableClients, ",") != strings.Join(wantClients, ",") {
		t.Fatalf("available clients = %#v, want %#v", got.AvailableClients, wantClients)
	}
	if got.Client != "" {
		t.Fatalf("no-arg mcp config should not select a client, got %q", got.Client)
	}
	if got.Config != nil {
		t.Fatalf("no-arg mcp config should list metadata only, got config %#v", got.Config)
	}
	if !got.Safety.LocalOnly || !got.Safety.GuidanceOnly || !got.Safety.DoesNotReadSecrets || !got.Safety.DoesNotWriteFiles || !got.Safety.DoesNotExecuteMCP || !got.Safety.MCPReadOnly {
		t.Fatalf("mcp config should be local guidance, no-preload, and read-only: %#v", got.Safety)
	}
	if got.Safety.Installs || got.Safety.CallsAPIs || got.Safety.Publishes || got.Safety.Signs || got.Safety.ApprovesLaunch {
		t.Fatalf("mcp config should not install, call APIs, publish, sign, or approve launch: %#v", got.Safety)
	}
	if !got.Safety.LocalOnlyNoPreload {
		t.Fatalf("mcp config should advertise localOnlyNoPreloadAnnotation safety: %#v", got.Safety)
	}
	if !containsString(got.Notes, "Set STRADDLE_TOKEN through your client's secure environment or secret manager. This command only names the env var; it does not set a token value.") {
		t.Fatalf("mcp config should mention env var names only in notes: %#v", got.Notes)
	}
	if strings.Contains(stdout, "fixture-secret-token-never-print") || strings.Contains(stdout, "STRADDLE_TOKEN=") || strings.Contains(stdout, "Bearer ") {
		t.Fatalf("mcp config leaked token-shaped output:\n%s", stdout)
	}
}

