func assertMCPClientConfig(t *testing.T, client string, config any) {
	t.Helper()

	cfg, ok := config.(map[string]any)
	if !ok {
		t.Fatalf("%s config should be an object, got %T", client, config)
	}
	switch client {
	case "claude-desktop", "cursor":
		servers, ok := cfg["mcpServers"].(map[string]any)
		if !ok {
			t.Fatalf("%s config should include mcpServers, got %#v", client, cfg)
		}
		straddle, ok := servers["straddle"].(map[string]any)
		if !ok {
			t.Fatalf("%s config should include mcpServers.straddle, got %#v", client, servers)
		}
		if straddle["command"] != "/opt/straddle/straddle-pp-mcp" {
			t.Fatalf("%s command = %#v", client, straddle["command"])
		}
		if _, ok := straddle["env"]; ok {
			t.Fatalf("%s config should not set env token values: %#v", client, straddle)
		}
	case "codex":
		if cfg["config_kind"] != "codex_local_stdio_fragment" {
			t.Fatalf("codex config_kind = %#v", cfg["config_kind"])
		}
		addCommand, ok := cfg["add_command"].([]any)
		if !ok {
			t.Fatalf("codex config should include add_command, got %#v", cfg)
		}
		want := []string{"codex", "mcp", "add", "straddle", "--", "/opt/straddle/straddle-pp-mcp"}
		if len(addCommand) != len(want) {
			t.Fatalf("codex add_command = %#v, want %#v", addCommand, want)
		}
		for i, wantPart := range want {
			if addCommand[i] != wantPart {
				t.Fatalf("codex add_command = %#v, want %#v", addCommand, want)
			}
		}
		toml, ok := cfg["toml"].(string)
		if !ok || !strings.Contains(toml, "[mcp_servers.straddle]") || !strings.Contains(toml, `command = "/opt/straddle/straddle-pp-mcp"`) {
			t.Fatalf("codex config should include TOML fragment, got %#v", cfg)
		}
		if strings.Contains(toml, "env") {
			t.Fatalf("codex config should not set env token values: %s", toml)
		}
	case "stdio":
		if cfg["command"] != "/opt/straddle/straddle-pp-mcp" {
			t.Fatalf("stdio command = %#v", cfg["command"])
		}
		args, ok := cfg["args"].([]any)
		if !ok || len(args) != 0 {
			t.Fatalf("stdio args = %#v, want empty array", cfg["args"])
		}
		envVarNames, ok := cfg["env_var_names"].([]any)
		if !ok || len(envVarNames) != 1 || envVarNames[0] != "STRADDLE_TOKEN" {
			t.Fatalf("stdio env_var_names = %#v, want STRADDLE_TOKEN only", cfg["env_var_names"])
		}
	default:
		t.Fatalf("unhandled client %q", client)
	}
}

